  ('ng-ev-011-pathmaker', 'Small Hatches (2; top)', 75, 'Each. Small target: Called Shot, -3 to strike.', 6),
  ('ng-ev-011-pathmaker', 'Armored Window Shutter/Gun Port (1; top, forward)', 70, 'Small target: Called Shot, -3 to strike.', 7),
  ('ng-ev-011-pathmaker', 'Treads (4)', 120, 'Each. Needs a Called Shot (no penalty), or damage goes to the Main Body.', 8),
