INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-crv05-crisis-response-vehicle', 1, 'APC Module Laser Cannon', '5D6 M.D. per blast', 1, '2,000 ft (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited, from its own Solid Oxide generator', NULL, 'APC module only. Roof mount, turning 360 degrees with a 30 degree up and down arc; a separate gunner is recommended.'),
  ('ng-crv05-crisis-response-vehicle', 2, 'APC Module Mini-Missile Launcher', 'By mini-missile type: tear gas, smoke or Hex; explosive 1D4x10 M.D.; plasma 1D6x10 M.D.', 1, 'One mile (1.6 km)', 'Singly or in volleys of 2, 3 or 4', '24, plus 24 more carried inside', NULL, 'APC module only. Its own turret turns 360 degrees with a 75 degree up and down arc.'),
  ('ng-crv05-crisis-response-vehicle', 3, 'Ram Prow', '2D6 M.D. tapping ram; 4D6 M.D. per high-speed ram at 50 mph (80 km) or more; 1D4x10 M.D. ramming a stationary object at 50 mph (80 km) or more, 4D6 M.D. slower', 1, NULL, NULL, NULL, NULL, 'SWAT and APC modules. Replaces the bumper.'),
  ('ng-ev-011-pathmaker', 1, 'Multi-Missile Launcher (Main Weapon)', 'As per missile type', 1, 'As per missile type', 'Short- and medium-range missiles singly or in pairs; mini-missiles singly or in volleys of 2 or 4', '3 short-range, 6 medium-range (three in each of two tubes) and 64 mini-missiles; a further full load can ride in the cargo bay', NULL, 'Main weapon on 60% of Pathmakers (pick it or the laser cannon). Fires short-range, medium-range and mini-missiles of any kind, aimed forward, 45 degrees up or down; to hit something to the side or rear the whole turret turns, using two melee attacks. Anti-armor, anti-monster and defense.'),
  ('ng-ev-011-pathmaker', 2, 'Laser Cannon (Main Weapon)', '1D4x10+6 M.D. per dual blast', 1, '4,000 ft (1,219 m)', 'Each blast uses one melee attack of the pilot or co-pilot', 'Effectively unlimited', NULL, 'The other main weapon choice, on 40% of Pathmakers. Same mount and arc as the missile launcher.'),
  ('ng-ev-011-pathmaker', 3, 'Optional: Light Vehicular Laser', '2D6 M.D.', 1, '2,000 ft (610 m)', NULL, 'Unlimited; tied to the power supply', NULL, 'One of up to two optional weapons, one front and one back. 27,000 credits fixed forward, with 20 M.D.C.; 150,000 more and 20 more M.D.C. in a turret turning 180 degrees.'),
  ('ng-ev-011-pathmaker', 4, 'Optional: Double-Barreled Light Vehicular Laser', '2D6 M.D. per single shot, 4D6 M.D. per simultaneous dual shot', 1, '2,000 ft (610 m)', NULL, NULL, NULL, 'Optional. 50,000 credits fixed forward, with 20 M.D.C.; 175,000 more and 30 more M.D.C. in a turret turning 180 degrees.'),
  ('ng-ev-011-pathmaker', 5, 'Optional: Medium Vehicular Laser', '4D6 M.D.', 1, '2,000 ft (610 m)', NULL, 'Unlimited; tied to the power supply', NULL, 'Optional. 48,000 credits fixed forward, with 25 M.D.C.; 180,000 more and 30 more M.D.C. in a turret turning 180 degrees.'),
  ('ng-ev-011-pathmaker', 6, 'Optional: Light Machine-Gun', '2D4x10 S.D.C. per 10-round burst, or 1D4 M.D. per 50-round burst', 1, '2,000 ft (610 m)', NULL, '2,400 rounds (48 bursts)', NULL, 'Optional. 10,400 credits.'),
  ('ng-ev-011-pathmaker', 7, 'Optional: Light Rail Gun', '6D6 M.D. per 20-round burst', 1, '3,000 ft (914 m)', NULL, '2,400 rounds (120 bursts)', NULL, 'Optional. 30 M.D.C.; fixed forward, or worked by a gunner and turning 180 degrees. 80,000 credits; 120,000 more and 30 more M.D.C. in a turret turning 180 degrees.'),
  ('ng-ev-011-pathmaker', 8, 'Optional: Mini-Missile Launcher', 'As per mini-missile type', 1, NULL, NULL, 'Eight mini-missiles', NULL, 'Optional. A small box launcher with 20 M.D.C. 150,000 credits.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 6 machines are in' AS assertion, count(*) AS got, 6 AS want
  FROM vehicles WHERE slug IN ('ng-apt-all-purpose-trailer', 'ng-hch-2000-big-bertha', 'ng-c100-cargonaut', 'ng-crv05-crisis-response-vehicle', 'ng-cw81-ermine', 'ng-ev-011-pathmaker');
SELECT 'their 57 locations are in' AS assertion, count(*) AS got, 57 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-apt-all-purpose-trailer', 'ng-hch-2000-big-bertha', 'ng-c100-cargonaut', 'ng-crv05-crisis-response-vehicle', 'ng-cw81-ermine', 'ng-ev-011-pathmaker');
SELECT 'their 11 weapon entries are in' AS assertion, count(*) AS got, 11 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-apt-all-purpose-trailer', 'ng-hch-2000-big-bertha', 'ng-c100-cargonaut', 'ng-crv05-crisis-response-vehicle', 'ng-cw81-ermine', 'ng-ev-011-pathmaker');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-apt-all-purpose-trailer', 'ng-hch-2000-big-bertha', 'ng-c100-cargonaut', 'ng-crv05-crisis-response-vehicle', 'ng-cw81-ermine', 'ng-ev-011-pathmaker') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

